(function(){
 'use strict';
 const say=(ar,en)=>state.lang==='ar'?ar:en,number=(x,d=1)=>Number.isFinite(x)?x.toFixed(d):'—';
 Object.assign(copy.ar,{hero:'قبل أن تغيّر الإشارة،<br><span>اختبر أثر القرار.</span>',heroCopy:'FlowTwin AI يرصد الحركة، ويتوقع الازدحام، ويختبر قرارات الإشارات في توأم رقمي. EcoTwin يكشف أثر كل قرار على الانتظار والحافلات والانبعاثات؛ وSafeCross يضيف حماية المشاة والجسور.',optimized:'تحكم تكيفي',labTitle:'جرّب القرار وشاهد سببه',recommended:'اتجاه الأخضر',honesty:'المتاح هنا: محرك حركة ومقارنة قرارات يعملان في المتصفح بمدخلات افتراضية. ربط الكاميرات والتنبؤ الميداني والتحكم بالأجهزة مراحل لم تنفذ بعد.'});
 Object.assign(copy.en,{hero:'Before the signal changes,<br><span>test the consequences.</span>',heroCopy:'FlowTwin AI observes traffic, anticipates congestion and tests signal decisions in a digital twin. EcoTwin reveals the effect on waiting, buses and emissions. SafeCross adds pedestrian and bridge protection.',optimized:'Adaptive control',labTitle:'Try a decision. See why it happens.',recommended:'Green direction',honesty:'Available here: a browser traffic engine and decision comparison with synthetic inputs. Camera integration, field forecasting and physical control are not implemented.'});
 copy.ar.scenarioDescriptions.ambulance='عند الثانية 6 يدخل طلب إسعاف من الغرب. يبدأ قطع الأخضر المتعارض فور الرصد، ثم الأصفر وإخلاء التقاطع، ثم يُثبت أخضر الإسعاف حتى يعبر. تابع الأزمنة الفعلية أدناه.';
 copy.en.scenarioDescriptions.ambulance='At second 6 an ambulance request enters from the west. Detection immediately starts preemption: amber, all-red clearance, then ambulance green held until it crosses. Follow the actual timestamps below.';
 copy.ar.scenarioDescriptions.congestion='يقارن المحرك إبقاء الأخضر وتبديل الاتجاه على أفق 24 ثانية. تُحتسب ثواني انتظار الحافلة بوزن 3 مقابل 1 للمركبة الأخرى، مع يسار محمي منفصل عن المستقيم واليمين، ومراحل أصفر وإخلاء آمنة.';
 copy.en.scenarioDescriptions.congestion='The engine compares holding green and switching over 24 seconds. A bus waiting second has weight 3 versus 1 for other vehicles, with protected left-turn phases separated from through/right, plus amber and all-red clearance.';
 copy.ar.scenarioDescriptions.offline='تستمر الحسابات في المتصفح نفسه. هذا اختبار قرار محلي؛ لا يوجد خادم سحابي متصل أو مزامنة ميدانية في هذه النسخة.';
 copy.en.scenarioDescriptions.offline='Calculations continue in this browser. This tests local decisions; there is no connected cloud server or field synchronization in this version.';
 let language='',lastPaint=0;
 function mount(){
  language=state.lang;
  let intro=document.querySelector('#idea-explainer');if(!intro){intro=document.createElement('section');intro.id='idea-explainer';document.querySelector('.intro').after(intro);}
  intro.innerHTML=`<div><span class="eyebrow">${say('الفكرة في ثلاث خطوات','THE IDEA IN THREE STEPS')}</span><h2>${say('نحوّل بيانات الطريق إلى قرار يمكن تفسيره.','Turn road observations into an explainable decision.')}</h2></div><ol>${[
   [say('يرصد ويتوقع','Observe & anticipate'),say('في النظام المستهدف: وكلاء رؤية على الحافة يستخرجون أعداد المركبات والطوابير والإسعاف من الكاميرات. في هذه التجربة يولّد محرك الحركة هذه المدخلات.','The intended edge vision agents extract vehicles, queues and ambulances from cameras. Here, the traffic engine generates those inputs.')],
   [say('يختبر قبل التنفيذ','Test before acting'),say('ينسخ الحالة الحالية ويحسب مسارين محتملين: إبقاء الأخضر أو تبديله. يعرض تكلفة كل خيار وسبب القرار المختار.','Copy the current state and evaluate two futures: hold green or switch. Inspect each cost and the selected action.')],
   [say('يقيس ويكشف المقايضة','Measure the trade-off'),say('نفس الطلب ونفس الزمن في تجربتين: تكيفية وثابتة. إن تحسن الإسعاف وتأخرت الحافلات، تظهر النتيجتان معًا.','Same demand and duration in adaptive and fixed runs. If the ambulance improves while buses wait longer, both results remain visible.')]
  ].map(([h,p],i)=>`<li><b>0${i+1}</b><h3>${h}</h3><p>${p}</p></li>`).join('')}</ol>`;
  let panel=document.querySelector('#decision-live');if(!panel){panel=document.createElement('section');panel.id='decision-live';document.querySelector('.workspace').after(panel);}
  panel.innerHTML=`<div class="decision-head"><div><span class="eyebrow">${say('سجل القرار الحي','LIVE DECISION RECORD')}</span><h2>${say('لماذا تغيرت الإشارة؟','Why did the signal change?')}</h2></div><button id="watch-priority">${say('شاهد لحظة طلب الإسعاف ↗','Watch the ambulance request ↗')}</button></div><div id="live-command"></div><div id="priority-timeline"></div><div class="decision-columns"><div><h3>${say('اختبار البدائل قبل القرار','Alternatives before the decision')}</h3><div id="candidate-results"></div><p class="decision-method">${say('أفق 24 ثانية؛ كلفة = انتظار المركبات + 2 × انتظار الحافلات (إجمالي وزن الحافلة 3). تُراجع الخيارات كل 4 ثوانٍ؛ الحد الأدنى 8 ثوانٍ للمستقيم و4 لليسار، والأقصى 24 و12 ثانية. توقع وفق مولّد الطلب الافتراضي، وليس نموذج ذكاء اصطناعي مدرّبًا. الانبعاثات تُقارن ولا تدخل هذه الكلفة.','24-second horizon. Cost = vehicle waiting + 2 × bus waiting (total bus weight 3). Options reviewed every 4 seconds; green limits are 8–24 s for through/right and 4–12 s for protected left. Forecasts use synthetic demand, not trained AI. Emissions are compared separately, not included in this cost.')}</p></div><div><h3>${say('نتيجة التجربة حتى الآن','Experiment result so far')}</h3><div id="decision-tradeoff"></div><div id="live-event-log"></div></div></div>`;
  document.querySelector('#watch-priority').onclick=async()=>{document.querySelector('[data-scenario="ambulance"]').click();document.querySelector('[data-mode="optimized"]').click();if(!await window.trafficUI.seek(5))return;document.querySelector('#eco-speed').value='1';document.querySelector('#eco-speed').onchange({target:{value:'1'}});window.trafficUI.toggle();document.querySelector('#decision-live').scrollIntoView({block:'start',behavior:'smooth'});};
 }
 const group=g=>g==='NS'?say('شمال–جنوب','North–south'):say('شرق–غرب','East–west');
 function paint(e,baseline,optimized){
  if(state.running&&language===state.lang&&performance.now()-lastPaint<150)return;lastPaint=performance.now();
  if(language!==state.lang||!document.querySelector('#decision-live'))mount();
  const a=e.snapshot(),b=baseline.snapshot(),p=e.priority,amb=e.emergency();
  let message=e.phase==='clearance'?say('أحمر للجميع — ننتظر خروج المركبات التي دخلت التقاطع.','ALL RED — waiting for vehicles already inside to clear.'):e.phase==='amber'?say('أصفر للاتجاه السابق — منع دخول مركبات جديدة.','AMBER — no new vehicles admitted.'):say('الأخضر الآن: ','GREEN NOW: ')+window.junctionStageName(e.stage,state.lang);
  if(state.mode==='baseline')message=say('مرجع ثابت بلا أولوية تكيفية. ','Fixed reference without adaptive priority. ')+message;
  else if(amb)message=say('طلب إسعاف نشط. ','Ambulance request active. ')+message;
  else if(p.crossed!==null)message=say('عبر الإسعاف؛ استؤنفت موازنة انتظار بقية المركبات. ','Ambulance passed; balancing other traffic again. ')+message;
  if(!state.running)message=(state.complete?say('انتهت التجربة · ','Experiment ended · '):a.time<.01?say('بانتظار التشغيل · ','Ready to start · '):say('متوقفة مؤقتًا · ','Paused · '))+message.replace(say('الأخضر الآن: ','GREEN NOW: '),say('المرحلة المحفوظة: ','Saved phase: '));
  document.querySelector('#live-command').textContent=message;
  document.querySelector('#live-command').dataset.phase=e.phase;
  const timeline=document.querySelector('#priority-timeline');timeline.hidden=state.scenario!=='ambulance';
  const clearance=e.events.find(x=>x.type==='clearance'&&p.detected!==null&&x.time>=p.detected);
  timeline.innerHTML=[[say('رصد الطلب','Detected'),p.detected],[say('بدء قطع الأخضر','Preemption starts'),p.amber],[say('إخلاء آمن','All-red clearance'),clearance?.time],[say('أخضر الإسعاف','Ambulance green'),p.green],[say('اكتمل العبور','Crossed'),p.crossed]].map(([title,value])=>`<div class="${Number.isFinite(value)?'reached':''}"><span>${title}</span><b dir="ltr">${number(value)} s</b></div>`).join('');
  const d=e.decisions.at(-1),candidate=document.querySelector('#candidate-results');
  candidate.innerHTML=d?`<p>${say('آخر مقارنة عند','Last comparison at')} <b dir="ltr">${number(d.time)} s</b> · ${say('توقع للـ','Forecast for the next ')} <b>${d.horizon}</b> ${say('ثانية التالية','seconds')}</p><p class="candidate-guide">${say('هذه الأرقام كلفة انتظار متوقعة؛ الأقل أفضل. تجمع انتظار كل المركبات مع وزن إضافي للحافلات، وليست زمن رحلة أو ثواني توفير.','These numbers are forecast waiting costs; lower is better. They combine all vehicle waiting with an extra bus weight, not journey times or seconds saved.')}</p><div class="candidate-options">${[[d.hold,say('إبقاء المرحلة','Hold phase'),say('تأجيل التبديل 4 ثوانٍ','Defer switching for 4 seconds')],[d.change,say('المرحلة التالية','Next phase'),say('بدء الأصفر ثم الإخلاء والتبديل','Start amber, then clearance and switch')]].map(([x,title,action])=>`<div class="${d.action===x.action?'chosen':''}"><h4>${title}</h4><p class="candidate-action">${action}</p><span class="candidate-cost-label">${say('كلفة الانتظار المتوقعة','Forecast waiting cost')}</span><b class="candidate-score" dir="ltr">${number(x.cost)}</b><small>${say('مركبة·ث موزونة','weighted vehicle·s')}</small><dl class="candidate-breakdown"><div><dt>${say('انتظار جميع المركبات','All-vehicle waiting')}</dt><dd dir="ltr">${number(x.waiting)}</dd></div><div><dt>${say('وزن الحافلات الإضافي (×2)','Extra bus weight (×2)')}</dt><dd dir="ltr">+ ${number(2*x.bus)}</dd></div></dl><small class="candidate-choice">${d.action===x.action?say('الخيار المختار آنذاك','Selected at that time'):say('الخيار المقارن','Alternative')}</small></div>`).join('')}</div><p class="candidate-difference">${say('فرق الكلفة بين الخيارين:','Cost difference between options:')} <b dir="ltr">${number(Math.abs(d.hold.cost-d.change.cost))}</b> ${say('مركبة·ث موزونة. هذا فرق توقع في مجموع الانتظار، وليس توفيرًا مقاسًا لرحلة واحدة.','weighted vehicle·s. This is a forecast difference in aggregate waiting, not a measured saving for one trip.')}</p>${amb?'<p>'+say('الأولوية الطارئة تتجاوز المقارنة العادية حتى عبور الإسعاف.','Emergency priority overrides normal comparison until the ambulance crosses.')+'</p>':''}`:`<p>${state.mode==='baseline'?say('التوقيت الثابت لا يقارن بدائل.','Fixed timing does not compare alternatives.'):amb?say('الأولوية الطارئة تتجاوز مقارنة الكلفة؛ بوابة الإخلاء تبقى إلزامية.','Emergency priority overrides the cost comparison; clearance remains mandatory.'):say('بانتظار أول قرار بعد حد الأخضر الأدنى.','Waiting for the first decision after minimum green.')}</p>`;
  const busDelta=a.busDelay-b.busDelay,waitDelta=a.waiting-b.waiting,co2Delta=a.co2-b.co2;
  const delta=(v,unit)=>(v>0?'+':'')+number(v,2)+' '+unit;
  document.querySelector('#decision-tradeoff').innerHTML=`<dl><div><dt>${say('تأخر الحافلات','Bus delay')}</dt><dd>${number(a.busDelay,2)} / ${number(b.busDelay,2)} s <strong class="${busDelta>.05?'loss':''}">${delta(busDelta,'s')}</strong></dd></div><div><dt>${say('انتظار جميع المركبات','All-vehicle waiting')}</dt><dd>${number(a.waiting,2)} / ${number(b.waiting,2)} s <strong class="${waitDelta>.05?'loss':''}">${delta(waitDelta,'s')}</strong></dd></div><div><dt>CO₂</dt><dd>${a.co2.toFixed(3)} / ${b.co2.toFixed(3)} kg <strong class="${co2Delta>.0005?'loss':''}">${co2Delta>0?'+':''}${co2Delta.toFixed(3)} kg</strong></dd></div></dl><p>${say('المعروض / المرجع الثابت. حافلات وصلت في كل تجربة: ','Displayed / fixed reference. Bus arrivals per run: ')}${e.busArrived}. ${say('حركات مكتملة: مستقيم / يسار / يمين: ','Completed straight / left / right: ')}${e.movementCrossings.straight} / ${e.movementCrossings.left} / ${e.movementCrossings.right}.</p><p class="${busDelta>.05?'tradeoff-warning':'tradeoff-note'}">${a.time<1?say('لم يبدأ القياس بعد.','Measurement has not started.'):busDelta>.05?say('الحافلات أسوأ الآن. لا نعتبر هذا تحسنًا شاملًا؛ الأولوية أو التبديل قد ينقلان الانتظار إلى اتجاه آخر.','Buses are worse right now. This is not an overall improvement; priority or switching can transfer waiting to another approach.'):say('النتيجة تخص الزمن والطلب الحاليين؛ لا تضمن تحسن جميع المؤشرات طوال التجربة.','This result applies to current demand and elapsed time; it does not guarantee every metric improves throughout the run.')}</p>`;
  const names={detected:say('رُصد طلب الإسعاف','Ambulance detected'),amber:say('بدء الأصفر','Amber started'),clearance:say('بدء الإخلاء','Clearance started'),green:say('فتح الأخضر','Green opened'),'priority-green':say('تثبيت أخضر الإسعاف','Ambulance green held'),'ambulance-crossed':say('عبر الإسعاف','Ambulance crossed'),decision:say('مقارنة البدائل','Alternatives compared')};
  document.querySelector('#live-event-log').innerHTML=e.events.slice(-4).reverse().map(x=>`<p><b dir="ltr">${number(x.time)} s</b> ${names[x.type]||x.type} · ${window.junctionStageName(x.stage??e.stage,state.lang)}</p>`).join('');
  document.querySelectorAll('[data-route-lane]').forEach(path=>{const emergency=amb&&e.mode==='optimized'&&amb.lane===Number(path.dataset.routeLane);path.setAttribute('stroke',emergency?'#ffbe87':'#9acaab');path.setAttribute('stroke-width',emergency?'5':'1');});
 }
 window.decisionUI={paint};translate();
})();
